// Use "take" to view a sample number of records in the table and check the data.
FleetTelemetry
| summarize Copies = count()
    by Timestamp, TripId, BusLine, StationNumber,
       ScheduleTime, PropertiesText = tostring(Properties)
| summarize
    SourceRows = sum(Copies),
    DistinctPayloadGroups = count(),
    ExactDuplicateExcess = sum(Copies - 1),
    DuplicateGroups = countif(Copies > 1),
    MaximumCopies = max(Copies)

// See how many records are in the table.
YOUR_TABLE_HERE
| count

// This query returns the number of ingestions per hour in the given table.
YOUR_TABLE_HERE
| summarize IngestionCount = count() by bin(ingestion_time(), 1h)
